from pathlib import Path
import hashlib,json,os,subprocess,sys,time
ROOT=Path(__file__).resolve().parents[3]
E=Path(__file__).resolve().parent
sys.path.insert(0,str(ROOT/'scripts/bench'))
from workloads import catalog
from run import write_json
WORKERS={'base':E/'base/benchmark_dsp','current':E/'current/benchmark_dsp'}
def invoke(args,out):
 out.parent.mkdir(parents=True,exist_ok=True)
 with out.open('w') as log:
  try:r=subprocess.run(args,cwd=ROOT,stdout=log,stderr=subprocess.STDOUT,timeout=240)
  except subprocess.TimeoutExpired:return {'ok':False,'error':'audit parent timeout'}
 return {'ok':r.returncode==0,'returncode':r.returncode}
def prepare():
 (E/'sources').mkdir(exist_ok=True);cases=[]
 for name,info in catalog().items():
  source=info['source'];source=source() if callable(source) else source
  path=E/'sources'/f'{name}.onda';path.write_text(source)
  cases.append({'name':name,'source':str(path),'kind':'builtin','warmup':info['warmup_blocks'],'max_output_abs':info.get('max_output_abs')})
 for path in sorted((ROOT/'examples').rglob('*.onda')):
  name='example-'+str(path.relative_to(ROOT/'examples')).removesuffix('.onda').replace('/','-')
  cases.append({'name':name,'source':str(path),'kind':'example','warmup':512,'max_output_abs':None})
 write_json(E/'cases.json',cases)
 write_json(E/'audit-identity.json',{'source_commit':subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip(),'worker_sha256':{k:hashlib.sha256(p.read_bytes()).hexdigest() for k,p in WORKERS.items()},'cases':len(cases),'timing':{'cpu':0,'sample_rate':48000,'block_size':128,'strict':True,'repetitions':5,'round_ms':50,'validation_blocks':8,'latency_blocks':512}})
 print('prepared',len(cases),flush=True)
def inspection():
 results=[]
 for n,case in enumerate(json.loads((E/'cases.json').read_text())):
  name=case['name'];directory=E/'inspection-fixed'/name
  args=[sys.executable,'scripts/bench/run.py','--source',case['source'],'--runner',str(WORKERS['current']),'--inspect-only','--backend','native','--output',str(directory),'--cpu','0','--timeout-seconds','180']
  result={'name':name,'kind':case['kind'],**invoke(args,E/'inspection-fixed-logs'/f'{name}.log')}
  mirs=list(directory.glob('*.mir.json'))
  if result['ok'] and mirs:
   mir=json.loads(mirs[0].read_text());interface=mir['interface'];types=mir['types']
   ports=interface['inputs']+interface['outputs']
   result.update(buffers=len(interface['buffers']),outputs=len(interface['outputs']),events=[x['name'] for x in interface['events']],scalar_ports=all(types[p['ty']]['kind']=='scalar' for p in ports))
   result['runnable']=bool(result['outputs'] and not result['buffers'] and result['scalar_ports'])
  else:result['runnable']=False
  results.append(result);write_json(E/'inspection.json',results)
  print(n+1,name,'OK' if result['ok'] else 'FAILED',flush=True)
def timings(mode):
 cases=json.loads((E/'cases.json').read_text());eligible={r['name'] for r in json.loads((E/'inspection.json').read_text()) if r.get('runnable')}
 results=[]
 for n,case in enumerate(c for c in cases if c['name'] in eligible):
  name=case['name'];order=['base','current'];order=order[n%2:]+order[:n%2]
  for worker in order:
   directory=E/mode/name/worker
   args=[sys.executable,'scripts/bench/run.py','--source',case['source'],'--runner',str(WORKERS[worker]),'--backend','native','--output',str(directory),'--ir','--cpu','0','--timeout-seconds','180','--repetitions','5','--round-ms','50','--warmup-blocks',str(case['warmup']),'--validation-blocks','8','--latency-blocks','512']
   if case['max_output_abs'] is not None:args+=['--max-output-abs',str(case['max_output_abs'])]
   result={'name':name,'worker':worker,'kind':case['kind'],**invoke(args,E/(mode+'-logs')/f'{name}-{worker}.log')}
   rows=list(directory.glob('*.native.json'))
   if result['ok'] and rows:result['row']=json.loads(rows[0].read_text())
   results.append(result);write_json(E/(mode+'.json'),results)
   print(n+1,name,worker,'OK' if result['ok'] else 'FAILED',flush=True)
if __name__=='__main__':
 if sys.argv[1]=='prepare':prepare()
 elif sys.argv[1]=='inspect':inspection()
 elif sys.argv[1]=='timings':timings('timings')

